#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { flattenCapabilities, loadModules } from '../src/registry.mjs';

const pluginRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outputPath = path.join(pluginRoot, 'skills', 'design', 'references', 'capabilities.md');

export function renderCapabilityIndex(modules) {
  const lines = [
    '<!-- Generated by scripts/build-capability-index.mjs. Do not edit manually. -->',
    '',
    '# Curated capabilities',
    '',
    'Choose the highest-specificity matching capability. A fallback is used only when no narrower capability matches.',
    '',
    '| Module | Version | Capability | Skill | Specificity | Fallback | Triggers | Scope | Combinable with |',
    '|---|---:|---|---|---:|---|---|---|---|',
  ];
  for (const capability of flattenCapabilities(modules).sort((a, b) => b.specificity - a.specificity || a.module.localeCompare(b.module))) {
    lines.push(`| ${capability.module} | ${capability.moduleVersion} | ${capability.id} - ${capability.title} | ${capability.skill} | ${capability.specificity} | ${capability.fallback ? 'yes' : 'no'} | ${(capability.triggers || []).join(', ')} | ${(capability.scope || []).join(', ')} | ${(capability.combinableWith || []).join(', ') || '-'} |`);
  }
  lines.push('', '## Module sources', '');
  for (const module of modules) {
    lines.push(`- \`${module.id}@${module.version}\` - ${module.license} - ${module.source.type} - ${module.source.url}`);
  }
  lines.push('');
  return lines.join('\n');
}

const rendered = renderCapabilityIndex(loadModules(pluginRoot));
if (process.argv.includes('--check')) {
  const current = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, 'utf8') : '';
  if (current !== rendered) {
    process.stderr.write('Capability index is stale. Run npm run build:capabilities.\n');
    process.exitCode = 1;
  } else {
    process.stdout.write('Capability index is current.\n');
  }
} else {
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, rendered);
  process.stdout.write(`Wrote ${path.relative(pluginRoot, outputPath)}.\n`);
}
